import com.example.starter.po.BerthPo;

/**
 * 泊位仓储。
 */
@Repository
public class BerthRepository {

    private static final RowMapper<BerthPo> MAPPER = (rs, n) -> new BerthPo(
            rs.getLong("id"),
            rs.getString("code"),
            rs.getBigDecimal("static_depth"),
