        } catch (EmptyResultDataAccessException ex) {
            return null;
        }
    }

    public List<BerthPo> findAll() {
        return jdbcTemplate.query(
                "SELECT id, code, static_depth, created_at FROM berth ORDER BY code", MAPPER);
    }
}

