    private MockMvc mockMvc;

    @MockBean
    private BerthAllocationService service;

    @Test
    void nonPositiveDraftReturns422() throws Exception {
        String body = """
                {
                  "requestId": "REQ-W1",
                  "vesselName": "合成船",
                  "draft": 0,
                  "safetyMargin": 0.20,
                  "berthCode": "B-01",
                  "startTime": "2026-10-01T08:00:00",
                  "endTime": "2026-10-01T10:00:00"
                }
                """;
